theorem restrict {D D' : Set X} {f a : X → E} {b : X → ℝ}
    (h : ErrorOn D f a b) (hD : D' ⊆ D) :
    ErrorOn D' f a b

theorem weaken {D : Set X} {f a : X → E} {b d : X → ℝ}
    (h : ErrorOn D f a b) (hbd : ∀ x ∈ D, b x ≤ d x) :
    ErrorOn D f a d

theorem trans {D : Set X} {f a c : X → E} {b d : X → ℝ}
    (hfa : ErrorOn D f a b) (hac : ErrorOn D a c d) :
    ErrorOn D f c (fun x ↦ b x + d x)

private theorem isOpen_domainCoord_image {Z : Set ℂ} (hZ : IsOpen Z)
    (U : Opens (LiftedDomain.{u} Z)) :
    IsOpen (domainCoord (Z := Z) '' (U : Set (LiftedDomain.{u} Z)))

private theorem mem_open_of_mem_domainCoord_image {Z : Set ℂ} (hZ : IsOpen Z)
    (U : Opens (LiftedDomain.{u} Z)) (x : LiftedDomain.{u} Z)
    (hx : domainCoord x ∈ domainCoord '' (U : Set (LiftedDomain.{u} Z))) : x ∈ U

private theorem ambientize_domainCoord {Z : Set ℂ} (hZ : IsOpen Z)
    {U : Opens (LiftedDomain.{u} Z)} (s : U → E) [Zero E] (x : U) :
    ambientize hZ s (domainCoord (x : LiftedDomain.{u} Z)) = s x

private theorem exp_mul_intervalIntegral (h : ℝ) {u v : ℝ} (huv : u ≤ v) :
    h * ∫ t in u..v, Real.exp (-h * t) =
      Real.exp (-h * u) - Real.exp (-h * v)

private theorem gaussChartASolution_eqOn_seriesDisk (a b c : ℂ) :
    Set.EqOn (gaussChartASolution a b c)
      (regularizedGaussHypergeometricSeriesSum a b c) (gaussChartA ∩ gaussSeriesDisk)

private theorem gaussChartBSolution_eqOn_seriesDisk (a b c : ℂ) :
    Set.EqOn (gaussChartBSolution a b c)
      (regularizedGaussHypergeometricSeriesSum a b c) (gaussChartB ∩ gaussSeriesDisk)

private theorem gaussChartSolutions_eqOn_inter (a b c : ℂ) :
    Set.EqOn (gaussChartASolution a b c) (gaussChartBSolution a b c)
      (gaussChartA ∩ gaussChartB)

private theorem regularizedGaussHypergeometric_eqOn_chartA (a b c : ℂ) :
    Set.EqOn (regularizedGaussHypergeometric a b c) (gaussChartASolution a b c)
      gaussChartA

private theorem regularizedGaussHypergeometric_eqOn_chartB (a b c : ℂ) :
    Set.EqOn (regularizedGaussHypergeometric a b c) (gaussChartBSolution a b c)
      gaussChartB

private theorem legendre_integral_factor (x₀ x : ℝ)
    (hx₀ : x₀ ∈ Ioo (-1 : ℝ) 1) (hx : x ∈ Ioo (-1 : ℝ) 1) :
    Complex.exp (-∫ t in x₀..x, legendreFirst t) = (((1 - x₀ ^ 2) / (1 - x ^ 2) : ℝ) : ℂ)

private lemma exists_dirichlet_limit :
    ∃ L : ℝ, Tendsto (fun R => ∫ u in (1 : ℝ)..R, dirichletIntegrand u)
      atTop (nhds L)

private lemma exists_cutoffTail_limit :
    ∃ L : ℝ, Tendsto (fun R => ∫ u in (1 : ℝ)..R, cutoffTailIntegrand u)
      atTop (nhds L)

private lemma transformed_positiveCutoffTail_eq_qCutoff_zero {x : ℝ} (hx : 0 < x) :
    (|(-1 : ℝ)| * x ^ ((-1 : ℝ) - 1)) •
        positiveCutoffTail (x ^ (-1 : ℝ)) = qCutoff 0 x

private lemma qCutoff_zero_right_substitution {δ : ℝ} (hδ0 : 0 < δ) (hδ1 : δ < 1) :
    (∫ x in δ..1, qCutoff 0 x) =
      ∫ u in (1 : ℝ)..δ⁻¹, cutoffTailIntegrand u

private lemma finiteCutoffPrimitive_right {c LQ t : ℝ} (ht : c < t) :
    finiteCutoffPrimitive c LQ t =
      2 * LQ - ∫ v in t..c + 1, qCutoff c v

private lemma pCutoff_right_integral {c δ : ℝ} (hδ0 : 0 < δ) (hδ1 : δ ≤ 1) :
    (∫ t in c + δ..c + 1, pCutoff c t) =
      -Real.log δ + (δ ^ 2 - 1) / 2

private lemma pCutoff_left_integral {c δ : ℝ} (hδ0 : 0 < δ) (hδ1 : δ ≤ 1) :
    (∫ t in c - 1..c - δ, pCutoff c t) =
      Real.log δ + (1 - δ ^ 2) / 2

private lemma qCutoff_right_substitution {c δ : ℝ} (hδ0 : 0 < δ) (hδ1 : δ < 1) :
    (∫ t in c + δ..c + 1, qCutoff c t) =
      ∫ x in δ..1, qCutoff 0 x

private lemma qCutoff_left_substitution {c δ : ℝ} (hδ0 : 0 < δ) (hδ1 : δ < 1) :
    (∫ t in c - 1..c - δ, qCutoff c t) =
      ∫ x in δ..1, qCutoff 0 x

private theorem gammaEndpointBase_integral :
    (∫ u in Ioi (0 : ℝ), gammaEndpointBase u) =
      Real.Gamma (1 / 2 : ℝ)

private theorem zero_improper (k : ℝ) (S : Finset ℝ)
    (hS : ∀ c ∈ S, k < c) :
    HasImproperIntegralAtTopExcept (fun _ : ℝ => (0 : ℝ)) k S (0 : ℝ)

private theorem weightedFJ_eq_indicator :
    (fun t : ℝ => Real.exp (-t) * FJ t) =
      (Ioi (1 : ℝ)).indicator (fun t => Real.exp (-t))

private theorem weightedFB_integral_eq_interval (h : ℝ) :
    (∫ t in Ioi (0 : ℝ), Real.exp (-h * t) * FB t) =
      ∫ t in (0 : ℝ)..1, Real.exp (-h * t) * FB t

private theorem weightedgI_eq_indicator (h : ℝ) :
    (fun t : ℝ => Real.exp (-h * t) * gI t) =
      (Icc (1 : ℝ) 2).indicator (fun t => Real.exp (-h * t))

private theorem weightedgI_integral {h : ℝ} (hh : 0 < h) :
    (∫ t in Ioi (0 : ℝ), Real.exp (-h * t) * gI t) =
      (Real.exp (-h) - Real.exp (-2 * h)) / h

private theorem weightedFI_tail_integral {h : ℝ} (hh : 0 < h) :
    (∫ t in Ioi (2 : ℝ), Real.exp (-h * t) * FI t) =
      Real.exp (-2 * h) / h

private theorem weightedFI_integral {h : ℝ} (hh : 0 < h) :
    (∫ t in Ioi (0 : ℝ), Real.exp (-h * t) * FI t) =
      (Real.exp (-h) - Real.exp (-2 * h)) / h ^ 2
